import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
const legacy = s => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
const check = (input, expected) => assert.equal(slugify(input), expected, JSON.stringify(input));

if (mode === 'latin') {
  const cases = [
    ['Crème Brûlée', 'creme-brulee'], ['Łódź', 'lodz'],
    ['ÀÁÂÃÄÅ àáâãäå', 'aaaaaa-aaaaaa'],
    ['ÇĆĈĊČ çćĉċč', 'ccccc-ccccc'],
    ['ÈÉÊË ĒĔĖĘĚ', 'eeee-eeeee'],
    ['ÌÍÎÏ ĨĪĬĮİ', 'iiii-iiiii'],
    ['ÑŃŅŇ ñńņň', 'nnnn-nnnn'],
    ['ÒÓÔÕÖ ŌŎŐ', 'ooooo-ooo'],
    ['ÙÚÛÜ ŨŪŬŮŰŲ', 'uuuu-uuuuuu'],
    ['ÝŸ ŔŖŘ ŚŜŞŠ ŹŻŽ', 'yy-rrr-ssss-zzz'],
    ['Øø Łł Đđ Ðð Ħħ Ŧŧ', 'oo-ll-dd-dd-hh-tt'],
    ['Ææ Œœ Ĳĳ ßẞ Þþ ſ', 'aeae-oeoe-ijij-ssss-thth-s'],
    ['Ǽǽ Ǣǣ Ǿǿ', 'aeae-aeae-oo'],
    ['Straße & smørrebrød, cœur!', 'strasse-smorrebrod-coeur'],
    ['ŁÓDŹ / ÆTHER / ŒUVRE', 'lodz-aether-oeuvre'],
    ['a\u0301b e\u0327\u0301c i\u0308d', 'ab-ec-id'],
    ['L\u0335o\u0301dz\u0301', 'lodz'],
    ['æ\u0301 ø\u0308 ß\u0301', 'ae-o-ss'],
    ['Crème 東京 Łódź Привет Καλημέρα', 'creme-東京-lodz-привет-καλημέρα'],
    ['  --Crème 2.0 / Æ & Ø-- ', 'creme-2-0-ae-o'],
  ];
  for (const [input, expected] of cases) check(input, expected);
  // Cover all canonically decomposable Latin letters, not just French accents.
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || !/^\p{Script=Latin}$/u.test(letter)) continue;
    const decomposed = letter.normalize('NFD');
    const plain = decomposed.replace(/\p{M}/gu, '');
    if (!/^[A-Za-z]+$/.test(plain)) continue;
    const expected = 'x' + plain.toLowerCase() + 'y';
    check('x' + letter + 'y', expected);
    check('x' + decomposed + 'y', expected);
  }
} else if (mode === 'preserve') {
  for (const input of [
    '', '   ', '---', 'Hello, World!', '  --Release 2.0--  ',
    'foo___bar...baz', 'a/b\\c', 'A\nB\tC', '123 ٤٥٦ １２３',
    'Привет мир', 'Ёж Йога', 'Καλημέρα κόσμε', 'ΆΈΉΊΌΎΏ ΐ ΰ',
    '東京 日本語 カタカナ ひらがな', '한글 한국어', '中文繁體',
    'العربية עברית', 'हिन्दी বাংলা ไทย', 'ქართული Հայերեն',
    'Hello 😀 World', 'a\u200db', 'a\u0000b', '𐐀𐐁 𐌰𐌱',
  ]) check(input, legacy(input));
  // Every non-Latin letter must retain the old lower-case/slug behavior.
  let batch = [];
  const flush = () => { const input = batch.join(' '); check(input, legacy(input)); batch = []; };
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (/^\p{L}$/u.test(letter) && !/^\p{Script=Latin}$/u.test(letter)) {
      batch.push(letter);
      if (batch.length === 256) flush();
    }
  }
  if (batch.length) flush();
} else {
  throw new Error('Expected latin or preserve');
}
